#include <Adafruit_I2CDevice.h>
#include <Adafruit_I2CRegister.h>
#include <Adafruit_I2CRegisterBit.h>

bool Adafruit_HUSB238::getCCStatus() {
  Adafruit_I2CRegister ccRegister = Adafruit_I2CRegister(i2c_dev, HUSB238_PD_STATUS1);
  Adafruit_I2CRegisterBit ccBit = Adafruit_I2CRegisterBit(&ccRegister, 6);  // 6th bit

  // Read the bit value
  bool status = ccBit.read();

  // Ensure the status is within the expected bounds (0 or 1)
  if (status != 0 && status != 1) {
    // Handle unexpected value (e.g., log error, throw exception)
    // For now, we assume the read operation is always successful
    // and the status is either 0 or 1.
  }

  return status;
}
